# Synthetic ladder for the Section 7.2 sampler: small problems, generated FROM the model,
# with the truth known, to find out which feature of the real data breaks the mixing.
#
#   julia -t 6 --project=. revision2_experiments/covid/synth_ladder.jl [nsweeps] [nchains]
#
# Everything is generated by covid4's own forward_sample from a hand-set (theta, phi, eps)
# and a prior draw of (beta, tau, D), so there is NO misspecification. Any failure to
# recover the truth is the sampler or the run length, nothing else.
#
# The ladder varies three things, each a hypothesis about what is actually hard:
#
#   OFFSET   how big Y_{i,t-1} is relative to the growth term theta'phi. On the real data
#            the counts are cumulative and reach 1e5-1e6 while daily growth is in the
#            hundreds, so the growth structure is a ~0.1% perturbation of the rate.
#            "low" starts every county at 0; "high" starts them at 20000.
#
#   OVERLAP  whether the waves are separated in time (bumps at t = 10, 30, 50) or piled on
#            top of each other (bumps at 25, 30, 35, and wider). Tests directly whether
#            overlapping waves trade mass.
#
#   K        fitting with the true number of factors, or with more than the data supports.
#
# For each arm we report BOTH the usual convergence diagnostics and, because the truth is
# known, actual recovery: relative error on the fitted growth term and on eps, coverage of
# the true growth by the 95% posterior interval, and cosine similarity between the true and
# fitted factor profiles after matching factors to the truth.

ROOTDIR = joinpath(@__DIR__, "../..")
include(joinpath(ROOTDIR, "models/covid/covid_final.jl"))
using Random, Printf, Statistics, LinearAlgebra, Combinatorics
using MCMCDiagnosticTools

nsweeps = length(ARGS) >= 1 ? parse(Int, ARGS[1]) : 3000
nchains = length(ARGS) >= 2 ? parse(Int, ARGS[2]) : 4
nkeep   = nsweeps ÷ 2
N, M, Ktrue, Q, Dmax = 100, 60, 3, 5, 9
println("Julia ", VERSION, "  threads = ", Threads.nthreads())
println("N = $N, M = $M, K_true = $Ktrue, Q = $Q, Dmax = $Dmax")
println("$nchains chains x $nsweeps sweeps, keeping the last $nkeep\n")

bump(t, centre, width) = exp(-0.5 * ((t - centre)/width)^2)

# theta: each county loads mostly on one factor, with a floor so nothing is exactly zero
function make_theta(N, K, seed)
    Random.seed!(seed)
    th = fill(0.1, N, K)
    for i in 1:N
        th[i, rand(1:K)] += 2.0 * rand()
    end
    return th
end

function make_phi(M, K, overlap)
    centres = overlap ? [25.0, 30.0, 35.0] : [10.0, 30.0, 50.0]
    widths  = overlap ? [15.0, 15.0, 15.0] : [5.0, 5.0, 5.0]
    ph = Matrix{Float64}(undef, K, M)
    for k in 1:K, t in 1:M
        ph[k, t] = 40.0 * bump(t, centres[k], widths[k]) + 0.5
    end
    return ph
end

# Generate one dataset from the model itself.
function make_data(overlap, offset, seed)
    genmodel = covid4(N, M, Ktrue, Q, Dmax, 1.0, 1.0, 100.0, 0.1, 0.5, 1.0,
                      0.01, 1.0, 1.0, 1.0, 1.0, 0.0, 0.0, false, false)
    Y0 = fill(offset == :high ? 20000 : 0, N, 1)
    info = Dict("Y0_N" => Y0)
    Random.seed!(seed)
    st = sample_prior(genmodel, info)         # supplies beta, tau, D from the model's prior
    th = make_theta(N, Ktrue, seed + 1)
    ph = make_phi(M, Ktrue, overlap)
    st["U_NK"] = th; st["V_KM"] = ph; st["eps"] = 2.0
    data, st = forward_sample(genmodel; state=st, info=info)
    truth = Dict("theta"=>th, "phi"=>ph, "eps"=>2.0, "growth"=>th*ph, "D"=>st["D_NM"])
    ratio = median(vec(th*ph) ./ max.(vec(Float64.(data["Y_NM"])), 1.0))
    return data, info, truth, ratio
end

function run_chain(model, data, info, seed, nsweeps, nkeep, cells)
    Random.seed!(seed)
    state = sample_prior(model, info)
    eps_d = Float64[]; mu_d = Vector{Vector{Float64}}()
    th_d = Vector{Matrix{Float64}}(); ph_d = Vector{Matrix{Float64}}()
    for s in 1:nsweeps
        (_dd, state) = backward_sample(model, data, state)
        if s > nsweeps - nkeep
            U = state["U_NK"]::Matrix{Float64}; V = state["V_KM"]::Matrix{Float64}
            push!(eps_d, state["eps"])
            push!(mu_d, Float64[sum(U[n,:] .* V[:,m]) for (n,m) in cells])
            push!(th_d, copy(U)); push!(ph_d, copy(V))
        end
    end
    return eps_d, mu_d, th_d, ph_d
end

safe(f, x) = try f(x) catch; NaN end
r3(A) = reshape(A, size(A,1), size(A,2), 1)
function ess_drift_rhat(A)   # A is (draws, chains, params)
    e = mean(filter(isfinite, [safe(x -> ess(r3(reshape(x, :, 1)); kind=:bulk)[1], A[:,c,p])
                               for c in 1:size(A,2), p in 1:size(A,3)]))
    h = nkeep ÷ 2; d = Float64[]
    for c in 1:size(A,2), p in 1:size(A,3)
        x = @view A[:,c,p]; s = std(x)
        s > 0 && push!(d, abs(mean(x[h+1:end]) - mean(x[1:h]))/s)
    end
    r = maximum(filter(isfinite, [safe(_ -> rhat(reshape(A[:,:,p], size(A,1), size(A,2), 1))[1], p)
                                  for p in 1:size(A,3)]))
    return e, (isempty(d) ? NaN : maximum(d)), r
end

cosv(a, b) = dot(a,b) / (norm(a)*norm(b) + eps())

function arm(label, overlap, offset, Kfit)
    data, info, truth, ratio = make_data(overlap, offset, 4242)
    model = covid4(N, M, Kfit, Q, Dmax, 1.0, 1.0, 100.0, 0.1, 0.5, 1.0,
                   0.01, 1.0, 1.0, 1.0, 1.0, 0.0, 0.0, false, false)
    Random.seed!(99)
    cells = [(rand(1:N), rand(1:M)) for _ in 1:100]
    res = Vector{Any}(undef, nchains)
    for c in 1:nchains
        t = @elapsed res[c] = run_chain(model, data, info, 500+c, nsweeps, nkeep, cells)
        @printf("    [%s] chain %d/%d done (%.1f min)\n", label, c, nchains, t/60); flush(stdout)
    end

    E = Array{Float64}(undef, nkeep, nchains, 1)
    for c in 1:nchains; E[:,c,1] = res[c][1]; end
    MU = Array{Float64}(undef, nkeep, nchains, length(cells))
    for c in 1:nchains, s in 1:nkeep, p in eachindex(cells); MU[s,c,p] = res[c][2][s][p]; end

    ee, ed, er = ess_drift_rhat(E)
    me, md, mr = ess_drift_rhat(MU)

    # recovery, pooling all chains (this is what a user of the output would do)
    gsum = zeros(N, M); n = 0
    for c in 1:nchains, s in 1:nkeep
        gsum .+= res[c][3][s] * res[c][4][s]; n += 1
    end
    ghat = gsum ./ n
    grel = mean(abs.(ghat .- truth["growth"]) ./ max.(truth["growth"], 1e-9))
    epshat = mean(mean(res[c][1]) for c in 1:nchains)

    # coverage of the true growth at the sampled cells
    cov95 = 0
    for (idx, (nn, mm)) in enumerate(cells)
        v = Float64[]
        for c in 1:nchains, s in 1:nkeep; push!(v, res[c][3][s][nn,:]' * res[c][4][s][:,mm]); end
        lo, hi = quantile(v, 0.025), quantile(v, 0.975)
        lo <= truth["growth"][nn,mm] <= hi && (cov95 += 1)
    end

    # factor recovery: match each TRUE factor to its best fitted factor on the loading
    # profile, then report the cosine similarity of the matched pair (theta and phi).
    thbar = mean(res[c][3][s] for c in 1:nchains for s in 1:nkeep) ./ 1
    phbar = mean(res[c][4][s] for c in 1:nchains for s in 1:nkeep) ./ 1
    cth = Float64[]; cph = Float64[]
    for kt in 1:Ktrue
        best = argmax([cosv(truth["theta"][:,kt], thbar[:,kf]) for kf in 1:Kfit])
        push!(cth, cosv(truth["theta"][:,kt], thbar[:,best]))
        push!(cph, cosv(truth["phi"][kt,:],   phbar[best,:]))
    end

    @printf("%-34s %6.4f %8.1f %6.2f %6.2f %8.1f %6.2f %6.2f %8.2f %6.2f %5.0f%% %6.2f %6.2f\n",
            label, ratio, ee, ed, er, me, md, mr, grel, epshat, 100*cov95/length(cells),
            mean(cth), mean(cph))
    # stdout is block-buffered when this is redirected to a file, so without an explicit
    # flush nothing is readable until the process exits -- which makes a 30-minute run
    # impossible to monitor.
    flush(stdout)
end

@printf("%-34s %6s %8s %6s %6s %8s %6s %6s %8s %6s %6s %6s %6s\n",
        "arm", "ratio", "epsESS", "epsDr", "epsR", "muESS", "muDr", "muR",
        "growth", "eps", "cov95", "cosTh", "cosPh")
@printf("%-34s %6s %8s %6s %6s %8s %6s %6s %8s %6s %6s %6s %6s\n",
        "", "", "", "", "", "", "", "", "relerr", "(2.0)", "", "", "")
println("-"^140)
arm("separated, low offset,   K=3", false, :low,  3)
arm("separated, high offset,  K=3", false, :high, 3)
arm("overlapping, low offset, K=3", true,  :low,  3)
arm("overlapping, high offset,K=3", true,  :high, 3)
arm("overlapping, high offset,K=5", true,  :high, 5)

println("\nratio = median(theta'phi / Y) -- how big the growth term is relative to the level")
println("Dr = within-chain drift |mean(2nd half)-mean(1st half)|/sd; R = split-Rhat")
println("growth relerr, cov95, cosTh, cosPh are RECOVERY against the known truth")
